  const receiver = sender.map((_, i) => node(`r${i}`, `TX${i + 1}`, [(i - 2.5) * 1.65, 0, 2.8], 'data', i < overlap ? `0x${i + 10}` : '?', i < overlap ? 'idle' : 'muted'));
  const frames = [f('Two overlapping mempools', 'Kısmen ortak iki işlem havuzu', `The receiver already has ${overlap} of the block’s six transactions.`, `Alıcı bloktaki altı işlemin ${overlap} tanesini zaten biliyor.`, [...sender, ...receiver], [], { metrics: [metric('Already known', 'Zaten bilinen', `${overlap}/6`)] })];
  const ids = sender.map((_, i) => node(`id${i}`, `#${i + 1}`, [(i - 2.5) * 1.65, .8, 0], 'token', i === ambiguous ? 'ab ?' : `${(i * 37 + 13).toString(16)}`, 'active'));
  frames.push(f('Send short identifiers', 'Kısa kimlikleri gönder', 'The sender announces compact identifiers instead of every complete transaction.', 'Gönderici her tam işlem yerine kısa kimlikler duyurur.', [...sender, ...ids, ...receiver], ids.map((v, i) => connect(`s${i}`, v.id, 'active'))));
  const matched = receiver.map((v, i) => ({ ...v, value: known(i) ? '✓' : i === ambiguous ? '?' : '—', status: known(i) ? 'success' as Status : 'warning' as Status }));
  frames.push(f('Fill from local memory', 'Yerel bellekten doldur', 'Unambiguous matches fill their slots. Missing or ambiguous identifiers stay unresolved.', 'Belirsiz olmayan eşleşmeler yuvaları doldurur. Eksik veya belirsiz kimlikler çözülmeden kalır.', [...ids, ...matched], ids.map((v, i) => connect(v.id, `r${i}`, known(i) ? 'success' : 'warning')), { metrics: [metric('Locally reconstructed', 'Yerelde kurulan', 6 - missing.length)] }));
  frames.push(f('Request unresolved positions', 'Çözülmeyen konumları iste', missing.length ? `The receiver requests ${missing.length} complete transactions.` : 'Every slot matched locally; no extra transaction round trip is needed.', missing.length ? `Alıcı ${missing.length} tam işlem ister.` : 'Her yuva yerelde eşleşti; ek işlem alışverişi gerekmez.', [...sender, ...matched], missing.map(i => connect(`r${i}`, `s${i}`, 'warning', '?')), { focus: missing.map(i => `r${i}`) }));
