  const row = (values: number[], prefix: string, z: number, mode: 'all' | 'difference' = 'all') => values.map((value, i) => node(`${prefix}${value}`, `TX${value}`, [(i - (values.length - 1) / 2) * 1.6, .1, z], 'data', '', mode === 'difference' ? result.difference.includes(value) ? 'active' : 'muted' : 'idle'));
  const rows = [...row(a, 'a', -2.4), ...row(b, 'b', 2.4)];
  const sketch = node('sketch', 'Δ', [0, 1, 0], 'gate', `cap=${capacity}`, 'active');
  const frames = [f('Compare knowledge', 'Bilgileri karşılaştır', `Each peer knows six transactions; ${overlap} are shared.`, `Her eş altı işlem biliyor; ${overlap} tanesi ortak.`, rows, [], { metrics: [metric('Shared items', 'Ortak öğeler', overlap)] })];
  frames.push(f('Exchange a compact sketch', 'Kısa özet paylaş', 'A reconciliation sketch has a capacity for differences, not for the entire set.', 'Uzlaştırma özetinin kapasitesi tüm kümeye değil, fark sayısına bağlıdır.', [...rows, sketch], [connect('a1', 'sketch'), connect(`b${b[0]}`, 'sketch')], { note: bi('This is a sketch-capacity model, not an implementation of Minisketch algebra.', 'Bu Minisketch cebri uygulaması değil, özet kapasitesi modelidir.') }));
  frames.push(f('Find the symmetric difference', 'Simetrik farkı bul', `${result.difference.length} transaction identities belong to only one peer.`, `${result.difference.length} işlem kimliğini yalnız bir eş biliyor.`, [...row(a, 'a', -2.4, 'difference'), ...row(b, 'b', 2.4, 'difference'), { ...sketch, value: `|Δ|=${result.difference.length}` }], [], { metrics: [metric('Difference size', 'Fark boyu', result.difference.length), metric('Capacity', 'Kapasite', capacity)] }));
  frames.push(f(result.decoded ? 'The difference fits' : 'Decoding needs a fallback', result.decoded ? 'Fark kapasiteye sığıyor' : 'Çözümleme dönüş yolu istiyor', result.decoded ? 'The sketch capacity is sufficient to recover the modeled difference.' : 'The difference exceeds capacity; this trace falls back to explicit announcements.', result.decoded ? 'Özet kapasitesi modellenen farkı bulmaya yeterli.' : 'Fark kapasiteyi aşıyor; bu akış açık duyurulara geri dönüyor.', [...rows, { ...sketch, status: result.decoded ? 'success' : 'warning', value: result.decoded ? '✓' : '×' }], [], { focus: ['sketch'] }));
