  const union = result.union.map((value, i) => node(`u${value}`, `TX${value}`, [(i % 6 - 2.5) * 1.6, .3, Math.floor(i / 6) * 2 - 1], 'data', '', 'success'));
  frames.push(f('Both peers know the union', 'İki eş birleşimi biliyor', 'The peers finish with the same identities. Capacity failure changed cost, not correctness.', 'Eşler aynı kimliklerle bitirdi. Kapasite hatası doğruluğu değil, maliyeti değiştirdi.', union, [], { metrics: [metric('Known by both', 'İkisinin bildiği', union.length, 'success')] }));
