  const followers = groups.flatMap((group, pi) => group.map((r, i) => node(`r${r.id}`, `P${pi}:${i}`, [(i - (group.length - 1) / 2) * 1.5, .1, -1.45 + pi * 2.5], 'block', i < Math.max(0, group.length - lag) ? `k${r.id}` : '…', i < Math.max(0, group.length - lag) ? 'success' : 'muted')));
