  const replicated = records.filter(r => groups[r.partition].findIndex(x => x.id === r.id) < Math.max(0, groups[r.partition].length - lag));
  const frames = [f('Place records into partitions', 'Kayıtları bölümlere yerleştir', 'A key selects a partition. Each partition starts its own offset sequence at zero.', 'Anahtar bir bölüm seçer. Her bölüm kendi ofset dizisini sıfırdan başlatır.', input, [], { metrics: [metric('Partitions', 'Bölümler', partitions), metric('Records', 'Kayıtlar', 6)] })];
  frames.push(f('Append to independent logs', 'Bağımsız günlüklere ekle', 'Within each partition, offsets follow append order. There is no cross-partition clock here.', 'Her bölümde ofsetler ekleme sırasını izler. Burada bölümler arası saat yok.', [...input, ...leaders], [...chains, ...records.map(r => connect(`k${r.id}`, `l${r.id}`, 'active'))]));
