  frames.push(f('Expose a replicated prefix', 'Çoğaltılan öneki görünür yap', 'This model permits reading only records present on both replicas.', 'Bu model yalnız iki kopyada da bulunan kayıtları okumaya açar.', [...committed, ...followers], chains, { metrics: [metric('Readable records', 'Okunabilen kayıtlar', replicated.length, 'success')] }));
  const consumed = groups.map(group => Math.min(read, Math.max(0, group.length - lag)));
  const cursors = groups.map((group, pi) => node(`c${pi}`, `C${pi}`, [(consumed[pi] - (group.length - 1) / 2) * 1.5, 1.45, -2.5 + pi * 2.5], 'token', `next=${consumed[pi]}`, 'active'));
  frames.push(f('Consumers keep separate bookmarks', 'Tüketiciler ayrı yer imleri tutar', 'Each cursor advances only through its readable prefix. Offsets need not match across partitions.', 'Her imleç yalnız okunabilir önekte ilerler. Bölümlerin ofsetleri eşleşmek zorunda değil.', [...committed, ...followers, ...cursors], groups.flatMap((group, pi) => group.slice(0, consumed[pi]).map(r => connect(`l${r.id}`, `c${pi}`, 'success'))), { metrics: [metric('Consumed records', 'Tüketilen kayıtlar', consumed.reduce((a, b) => a + b, 0))] }));
  frames.push(f('Local order, local progress', 'Yerel sıra, yerel ilerleme', 'Equal offsets in different partitions do not establish a global event order.', 'Farklı bölümlerde eşit ofsetler küresel olay sırası oluşturmaz.', [...committed, ...cursors], chains, { metrics: consumed.map((value, i) => metric(`P${i} next offset`, `P${i} sonraki ofset`, value)) }));
