const BLOOM_WORDS = ['apple', 'banana', 'cherry', 'date', 'elder', 'fig', 'grape', 'kiwi'];
export function bloomPositions(word: string, size: number, hashes = 3): number[] { return Array.from({ length: hashes }, (_, i) => hash32(`${i}:${word}`) % size); }
