  const input = node('word', 'word', [0, 1.4, -3.8], 'token', 'apple', 'active');
  const frames = [f('Start with zero bits', 'Sıfır bitlerle başla', 'A compact array records hash positions, not complete words.', 'Kısa dizi tam sözcükleri değil, hash konumlarını saklar.', [...tiles(Array<number>(size).fill(0)), input], [], { metrics: [metric('Bits', 'Bitler', size), metric('Hashes per word', 'Sözcük başına hash', 3)] })];
  frames.push(f('Insert a word', 'Bir sözcük ekle', 'Three hashes choose bit positions. Insertion sets each selected bit to one.', 'Üç hash bit konumları seçer. Ekleme seçilen bitlerin her birini bire çevirir.', [...tiles(first, bloomPositions('apple', size)), input], bloomPositions('apple', size).map(i => connect('word', `b${i}`, 'active')), { focus: bloomPositions('apple', size).map(i => `b${i}`) }));
  frames.push(f('Reuse bits across words', 'Bitleri sözcükler arasında paylaş', `Inserted: ${words.join(', ')}. Different words may set the same bits.`, `Eklenenler: ${words.join(', ')}. Farklı sözcükler aynı bitleri açabilir.`, tiles(bits), [], { metrics: [metric('Bits set', 'Açık bitler', `${bits.filter(Boolean).length}/${size}`)] }));
