  frames.push(f('Hash the query', 'Sorguyu hashle', `The query checks positions ${positions.join(', ')} using the same hash functions.`, `Sorgu aynı hash işlevleriyle ${positions.join(', ')} konumlarını denetler.`, [...tiles(bits), queryNode], positions.map(i => connect('word', `b${i}`, 'active')), { focus: positions.map(i => `b${i}`) }));
  frames.push(f(maybe ? 'All queried bits are one' : 'At least one bit is zero', maybe ? 'Sorgulanan tüm bitler bir' : 'En az bir bit sıfır', maybe ? 'The filter answers “possibly present”. It cannot identify which word set these bits.' : 'A zero proves this word was never inserted into this filter.', maybe ? 'Filtre “belki var” der. Bu bitleri hangi sözcüğün açtığını ayıramaz.' : 'Sıfır, bu sözcüğün bu filtreye hiç eklenmediğini kanıtlar.', [...tiles(bits, positions), queryNode], positions.map(i => connect(`b${i}`, 'word', bits[i] ? 'success' : 'error'))));
